-- Neighborhood Guide for the suburban pilot cities: Parma, Brook Park and Lakewood. Built on 2026-11-27 from each city's
-- official website (council, police, parks and recreation, human services pages), Cuyahoga County Public Library and
-- Lakewood Public Library listings, and Greater Cleveland Food Bank partner listings. Items marked VERIFY in the review
-- notes came from a secondary directory and should be confirmed before launch.
-- Council members use kind 'council', not 'ward', so Cleveland ward-meeting imports (which match kind 'ward') never reach the suburbs.
-- Re-running replaces only the items this file created (sources other than 'Added by Nabora').
begin;
delete from neighborhood.guide_items where kind <> 'custom' and area_id in ('parma','brook-park','lakewood');
insert into neighborhood.guide_items(area_id,section,kind,name,detail,address,phone,url,source,sort) values
